<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Data Pemutusan</h1><p class="mt-1 text-sm text-slate-500">Kelola riwayat tindakan pemutusan pelanggan.</p></div><?php if (Auth::isAdmin()): ?><a href="<?= e(url('/pemutusan/create')) ?>" class="inline-flex items-center justify-center rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark">+ Tambah Pemutusan</a><?php endif; ?></section><section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><form class="flex gap-3" method="get"><div class="relative flex-1"><span class="absolute left-3 top-3 text-slate-400">⌕</span><input name="q" value="<?= e($search) ?>" class="form-input pl-9" placeholder="Cari NPA atau nama pelanggan"></div><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Cari</button><a href="<?= e(url('/pemutusan')) ?>" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600">Reset</a></form><div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($data['rows']): ?><div class="table-wrap"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">NPA</th><th class="px-5 py-3">Pelanggan</th><th class="px-5 py-3">Tanggal</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Tindakan</th><th class="px-5 py-3">Biaya</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($data['rows'] as $row): ?><tr><td class="px-5 py-4 font-mono text-xs font-semibold text-primary"><?= e($row['npa']) ?></td><td class="px-5 py-4"><a href="<?= e(url('/pelanggan/' . rawurlencode($row['npa']))) ?>" class="font-semibold text-slate-800 hover:text-primary"><?= e($row['nama_pelanggan']) ?></a></td><td class="px-5 py-4 text-slate-600"><?= e(formatTanggal($row['tgl_pemutusan'])) ?></td><td class="px-5 py-4"><span class="badge badge-neutral"><?= e($row['status_pemutusan']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= e($row['jenis_tindakan']) ?></td><td class="px-5 py-4 font-semibold text-slate-800"><?= e(formatRupiah($row['biaya_tindakan'])) ?></td><td class="px-5 py-4 text-right"><?php if (Auth::isAdmin()): ?><a class="font-semibold text-primary hover:underline" href="<?= e(url('/pemutusan/' . $row['id_pemutusan'] . '/edit')) ?>">Ubah</a><?php else: ?><span class="text-slate-400">Hanya baca</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada data pemutusan'; $emptyText='Tambahkan tindakan pemutusan pertama untuk pelanggan.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div><?php require root_path('app/Views/components/pagination.php'); ?></section>
